/* ===== module: core/email-sync.js ===== */
/* Email-provider tag sync for the subscription prefs (#511/#512) -- this is
   marketing-tag sync, NOT app-data sync and NOT Supabase. */
/* Module map (v1.006) -- Key: queueEmailSync(), emailSyncTagMap(). Depends on:
   state.subscriptions (core/state.js), Sync.lastAuthEmail (call time). */
/* #512 (user 2026-09-16): EmailOctopus sync for the #511 subscription
   prefs. The app never holds the EmailOctopus API key — a Cloudflare Worker
   (infra/emailoctopus-worker.js) owns it as an encrypted secret and exposes
   POST /subscribe. This module maps the three prefs onto the list's three
   tags and calls the worker:
     appUpdates -> "app-updates", marketing -> "newsletter", tips -> "app-tips"
   Sync triggers: any setSubscription/setAllSubscriptions call (state.js
   hooks queueEmailSync, debounced), sign-in (sync-auth.js handleAuthChange
   flushes prefs that were set while signed out), and the online event
   (retries a failed attempt).
   Only signed-in users have a verified email (Sync.lastAuthEmail); signed-out
   prefs stay local until sign-in, per the parked #512 plan. Failures are
   silent and retried later — prefs always work locally regardless of the
   worker's reachability. A per-email+tags hash skips no-op syncs. */
const EMAIL_SYNC_WORKER_URL='https://kohlrabi.us/api/email/subscribe';
const EMAIL_SYNC_DEBOUNCE_MS=2000;
const EO_TAG_FOR_KEY={appUpdates:'app-updates',marketing:'newsletter',tips:'app-tips'};
let emailSyncTimer=0;
/* Maps the three subscription prefs onto EmailOctopus tag booleans. */
function emailSyncTagMap(){
  const map={};
  try{
    SUBSCRIPTION_KEYS.forEach(k=>{map[EO_TAG_FOR_KEY[k]]=subscriptionOn(k);});
  }catch(_){/* state not ready; caller treats as no-op */}
  return map;
}
/* Hashes email+tags so no-op syncs can be skipped. */
function emailSyncHashFor(email,tags){
  return String(email)+'|'+SUBSCRIPTION_KEYS.map(k=>tags[EO_TAG_FOR_KEY[k]]?'1':'0').join('');
}
/* Debounces an EmailOctopus subscription sync. */
function queueEmailSync(){
  try{if(emailSyncTimer)clearTimeout(emailSyncTimer);}catch(_){}
  emailSyncTimer=setTimeout(()=>{
    emailSyncTimer=0;
    try{syncEmailSubscriptions().catch(()=>{});}catch(_){}
  },EMAIL_SYNC_DEBOUNCE_MS);
}
/* Pushes the subscription tags to EmailOctopus; returns {ok, reason}. */
async function syncEmailSubscriptions(){
  let email='';
  try{email=(typeof Sync!=='undefined'&&Sync&&Sync.lastAuthEmail)||'';}catch(_){}
  email=String(email).trim();
  if(!email||email.indexOf('@')<0)return{ok:false,reason:'signed-out'};
  const tags=emailSyncTagMap();
  let prev='';
  try{prev=(typeof state!=='undefined'&&state&&state.emailSyncHash)||'';}catch(_){}
  const hash=emailSyncHashFor(email,tags);
  if(hash===prev)return{ok:true,reason:'unchanged'};
  const anyOn=Object.keys(tags).some(t=>tags[t]===true);
  /* Never subscribed and nothing opted in: no contact to create, skip the call. */
  if(!anyOn&&!prev)return{ok:true,reason:'nothing-to-sync'};
  let res=null;
  try{
    res=await fetch(EMAIL_SYNC_WORKER_URL,{
      method:'POST',
      headers:{'content-type':'application/json'},
      body:JSON.stringify({email:email,tags:tags}),
    });
  }catch(_){return{ok:false,reason:'network'};}
  if(!res||!res.ok)return{ok:false,reason:'worker-'+((res&&res.status)||'error')};
  let data=null;
  try{data=await res.json();}catch(_){}
  if(!data||data.ok!==true)return{ok:false,reason:'worker-error'};
  try{
    state.emailSyncHash=hash;
    if(typeof schedulePersist==='function')schedulePersist();
  }catch(_){}
  return{ok:true,reason:'synced'};
}
/* Retry a failed sync when connectivity returns. */
try{
  if(typeof window!=='undefined'&&window&&typeof window.addEventListener==='function'){
    window.addEventListener('online',()=>{try{queueEmailSync();}catch(_){}});
  }
}catch(_){}
